class _ShellParseBudgetExceeded(RuntimeError):
    """Raised when conservative shell parsing must fail closed."""


def _decode_ansi_c_string(value: str) -> str | None:
    """Decode Bash ANSI-C quoting, returning ``None`` for unusable NUL data."""

    simple_escapes = {
        "a": "\a",
        "b": "\b",
        "e": "\x1b",
        "E": "\x1b",
        "f": "\f",
        "n": "\n",
        "r": "\r",
        "t": "\t",
        "v": "\v",
        "\\": "\\",
        "'": "'",
        '"': '"',
        "?": "?",
    }
    decoded: list[str] = []
    index = 0
    while index < len(value):
        if value[index] != "\\":
            decoded.append(value[index])
            index += 1
            continue
        if index + 1 >= len(value):
            decoded.append("\\")
            break

        escape = value[index + 1]
        if escape in simple_escapes:
            decoded.append(simple_escapes[escape])
            index += 2
            continue
        if escape in "\r\n":
            index += 2
            if escape == "\r" and index < len(value) and value[index] == "\n":
                index += 1
            continue
        if escape == "c" and index + 2 < len(value):
            control = ord(value[index + 2].upper()) ^ 0x40
            if control == 0:
                return None
            decoded.append(chr(control))
            index += 3
            continue
        if escape == "x":
            cursor = index + 2
            while (
                cursor < len(value)
                and cursor < index + 4
                and value[cursor] in "0123456789abcdefABCDEF"
            ):
                cursor += 1
            if cursor == index + 2:
                decoded.append("\\x")
                index += 2
                continue
            codepoint = int(value[index + 2 : cursor], 16)
            if codepoint == 0:
                return None
            decoded.append(chr(codepoint))
            index = cursor
            continue
        if escape in {"u", "U"}:
            limit = index + (6 if escape == "u" else 10)
            cursor = index + 2
            while (
                cursor < len(value)
                and cursor < limit
                and value[cursor] in "0123456789abcdefABCDEF"
            ):
                cursor += 1
            if cursor == index + 2:
                decoded.append("\\" + escape)
                index += 2
                continue
            codepoint = int(value[index + 2 : cursor], 16)
            if codepoint == 0 or codepoint > 0x10FFFF:
                return None
            decoded.append(chr(codepoint))
            index = cursor
            continue
        if escape in "01234567":
            cursor = index + 1
            digit_limit = index + (5 if escape == "0" else 4)
            while (
                cursor < len(value)
                and cursor < digit_limit
                and value[cursor] in "01234567"
            ):
                cursor += 1
            codepoint = int(value[index + 1 : cursor], 8) & 0xFF
            if codepoint == 0:
                return None
            decoded.append(chr(codepoint))
            index = cursor
            continue

        # Bash preserves the backslash for an unknown ANSI-C escape.
        decoded.extend(("\\", escape))
        index += 2

    return "".join(decoded)


def _parse_heredoc(
    command: str,
    position: int,
) -> tuple[str, bool, bool, int] | None:
    """Parse a ``<<`` redirection at ``position``.

    Return ``(delimiter, strip_tabs, quoted, end_position)``.  Here-strings
    (``<<<``) are intentionally excluded.
    """

    if (
        not command.startswith("<<", position)
        or command.startswith("<<<", position)
        or (position > 0 and command[position - 1] == "<")
    ):
        return None

    cursor = position + 2
    strip_tabs = cursor < len(command) and command[cursor] == "-"
    if strip_tabs:
        cursor += 1
    while cursor < len(command) and command[cursor] in " \t":
        cursor += 1
    if cursor >= len(command) or command[cursor] in "\r\n":
        return None

    delimiter: list[str] = []
    quoted = False
    while cursor < len(command):
        char = command[cursor]
        following = command[cursor + 1] if cursor + 1 < len(command) else ""
        ansi_c_quote = char == "$" and following == "'"
        locale_quote = char == "$" and following == '"'
        if ansi_c_quote or locale_quote:
            quoted = True
            if locale_quote:
                # The runtime locale may translate $"...". Without the exact
                # delimiter, do not mask any subsequent command as heredoc data.
                return None
            cursor += 1
            char = command[cursor]
            following = command[cursor + 1] if cursor + 1 < len(command) else ""
        if char == "$" and following == "(":
            closing = _command_substitution_close(
                command,
                cursor + 1,
                len(command),
            )
            if closing is None:
                return None
            raw_substitution = command[cursor : closing + 1]
            if any(
                marker in raw_substitution
                for marker in ("'", '"', "\\", "\r", "\n")
            ):
                # Exact quote removal inside a delimiter substitution is
                # ambiguous here. Fail open instead of masking later commands.
                return None
            delimiter.append(raw_substitution)
            cursor = closing + 1
            continue
        if char.isspace() or char in ";&|()<>":
            break
        if char == "'":
            quoted = True
            if ansi_c_quote:
                cursor += 1
                raw_ansi_c: list[str] = []
                while cursor < len(command) and command[cursor] != "'":
                    following = (
                        command[cursor + 1] if cursor + 1 < len(command) else ""
                    )
                    if command[cursor] == "\\" and following:
                        raw_ansi_c.extend(("\\", following))
                        cursor += 2
                    else:
                        raw_ansi_c.append(command[cursor])
                        cursor += 1
                if cursor >= len(command):
                    return None
                decoded_ansi_c = _decode_ansi_c_string("".join(raw_ansi_c))
                if decoded_ansi_c is None:
                    return None
                delimiter.append(decoded_ansi_c)
                cursor += 1
                continue
            closing = command.find("'", cursor + 1)
            if closing < 0:
                return None
            delimiter.append(command[cursor + 1 : closing])
            cursor = closing + 1
            continue
        if char == '"':
            quoted = True
            cursor += 1
            while cursor < len(command) and command[cursor] != '"':
                following = command[cursor + 1] if cursor + 1 < len(command) else ""
                if command[cursor] == "\\" and following:
                    if following in {'$', "`", '"', "\\"}:
                        delimiter.append(following)
                        cursor += 2
                    elif following in {"\n", "\r"}:
                        cursor += 2
                        if (
                            following == "\r"
                            and cursor < len(command)
                            and command[cursor] == "\n"
                        ):
                            cursor += 1
                    else:
                        delimiter.append("\\")
                        cursor += 1
                else:
                    delimiter.append(command[cursor])
                    cursor += 1
            if cursor >= len(command):
                return None
            cursor += 1
            continue
        if char == "\\" and following:
            if following in {"\n", "\r"}:
                cursor += 2
                if (
                    following == "\r"
                    and cursor < len(command)
                    and command[cursor] == "\n"
                ):
                    cursor += 1
                continue
            quoted = True
            delimiter.append(following)
            cursor += 2
            continue
        delimiter.append(char)
        cursor += 1

    if not delimiter:
        return None
    return "".join(delimiter), strip_tabs, quoted, cursor


def _line_break(command: str, start: int) -> tuple[int, int]:
    """Return ``(line_end, next_line_start)`` from ``start``."""

    cursor = start
    while cursor < len(command) and command[cursor] not in "\r\n":
        cursor += 1
    if cursor >= len(command):
        return len(command), len(command)
    next_line = cursor + 1
    if command[cursor] == "\r" and next_line < len(command) and command[next_line] == "\n":
        next_line += 1
    return cursor, next_line


def _command_substitution_close(
    command: str,
    open_position: int,
    limit: int,
) -> int | None:
    """Find the ``)`` paired with a shell ``$(`` opener."""

    body = command[open_position + 1 : limit]
    body_contexts = _shell_context_map(body)
    case_pattern_closes = _case_pattern_close_positions(body)
    depth = 1
    for offset, char in enumerate(body):
        if body_contexts[offset] != _EXECUTABLE_CONTEXT:
            continue
        if char == "(":
            depth += 1
        elif char == ")":
            if offset in case_pattern_closes:
                continue
            depth -= 1
            if depth == 0:
                return open_position + 1 + offset
    return None


def _backtick_substitution_close(
    command: str,
    open_position: int,
    limit: int,
) -> int | None:
    """Find an unescaped closing backtick in an expanding heredoc body."""

    index = open_position + 1
    while index < limit:
        if command[index] == "\\" and index + 1 < limit:
            index += 2
            continue
        if command[index] == "`":
            return index
        index += 1
    return None


def _heredoc_body_bounds(
    command: str,
    start: int,
    end: int,
    *,
    terminated: bool,
) -> tuple[int, int]:
    """Exclude the leading and terminator lines from a heredoc range."""

    _, body_start = _line_break(command, start)
    if not terminated:
        return body_start, end
    last_cr = command.rfind("\r", body_start, end)
    last_lf = command.rfind("\n", body_start, end)
    terminator_break = max(last_cr, last_lf)
    body_end = terminator_break if terminator_break >= body_start else body_start
    return body_start, body_end


def _heredoc_ranges(
    command: str,
    newline_position: int,
    pending: list[tuple[str, bool, bool]],
) -> tuple[list[tuple[int, int, bool, bool]], int]:
    """Locate pending heredoc bodies and the final terminator newline.

    Ranges begin at the preceding newline because deny regexes include that
    newline in their command-position match.  The final terminator newline is
    excluded so a real command on the following line remains executable.
    """

    _, cursor = _line_break(command, newline_position)
    marker = newline_position
    ranges: list[tuple[int, int, bool, bool]] = []
    resume = len(command)

    for delimiter, strip_tabs, quoted in pending:
        while cursor <= len(command):
            line_end, next_line = _line_break(command, cursor)
            line = command[cursor:line_end]
            candidate = line.lstrip("\t") if strip_tabs else line
            if candidate == delimiter:
                resume = line_end
                ranges.append((marker, resume, quoted, True))
                cursor = next_line
                marker = resume
                break
            if line_end >= len(command):
                ranges.append((marker, len(command), quoted, False))
                return ranges, len(command)
            cursor = next_line

    return ranges, resume


_LITERAL_CONTEXT = 0
_EXECUTABLE_CONTEXT = 1
_LINE_CONTINUATION = 2
_EXECUTABLE_CONTEXTS = frozenset({"normal", "command_substitution", "backtick"})


def _mark_unquoted_heredoc_continuations(
    command: str,
    start: int,
    end: int,
    contexts: list[int],
) -> None:
    """Mark active backslash-newline pairs inside an expanding heredoc."""

    index = start
    while index < end:
        if command[index] not in "\r\n":
            index += 1
            continue
        backslashes = 0
        cursor = index - 1
        while cursor >= start and command[cursor] == "\\":
            backslashes += 1
            cursor -= 1
        if backslashes % 2:
            contexts[index] = _LINE_CONTINUATION
            if (
                command[index] == "\r"
                and index + 1 < end
                and command[index + 1] == "\n"
            ):
                contexts[index + 1] = _LINE_CONTINUATION
                index += 1
        index += 1


def _mark_unquoted_heredoc_expansions(
    command: str,
    start: int,
    end: int,
    contexts: list[int],
    *,
    terminated: bool,
) -> None:
    """Mark only command/backtick substitutions in unquoted heredoc data."""

    body_start, body_end = _heredoc_body_bounds(
        command,
        start,
        end,
        terminated=terminated,
    )
    budget_index = body_start
    substitution_count = 0
    while budget_index < body_end:
        following = (
            command[budget_index + 1]
            if budget_index + 1 < body_end
            else ""
        )
        if (
            command[budget_index] == "\\"
            and following in {"\\", "$", "`", "\r", "\n"}
        ):
            budget_index += 2
            continue
        if (
            command[budget_index] == "$"
            and following == "("
            and not command.startswith("$((", budget_index)
        ):
            substitution_count += 1
            if substitution_count > _MAX_HEREDOC_SUBSTITUTION_SCANS:
                raise _ShellParseBudgetExceeded
            budget_index += 2
            continue
        budget_index += 1

    index = body_start
    while index < body_end:
        char = command[index]
        following = command[index + 1] if index + 1 < body_end else ""
        if char == "\\" and following in {"\\", "$", "`", "\r", "\n"}:
            index += 2
            if (
                following == "\r"
                and index < body_end
                and command[index] == "\n"
            ):
                index += 1
            continue
        prompt_transform = _PROMPT_TRANSFORM.match(command, index, body_end)
        if prompt_transform is not None:
            contexts[index] = _EXECUTABLE_CONTEXT
            index = prompt_transform.end()
            continue
        if (
            char == "$"
            and following == "("
            and not command.startswith("$((", index)
        ):
            close = _command_substitution_close(command, index + 1, body_end)
            if close is None:
                index += 2
                continue
            inner = command[index + 2 : close]
            inner_contexts = _shell_context_map(inner)
            contexts[index + 1] = _EXECUTABLE_CONTEXT
            contexts[index + 2 : close] = inner_contexts[:-1]
            index = close + 1
            continue
        if char == "`":
            close = _backtick_substitution_close(command, index, body_end)
            if close is None:
                index += 1
                continue
            inner = command[index + 1 : close]
            inner_contexts = _shell_context_map(inner)
            contexts[index] = _EXECUTABLE_CONTEXT
            contexts[index + 1 : close] = inner_contexts[:-1]
            index = close + 1
            continue
        index += 1


def _conditional_opens_at(command: str, position: int) -> bool:
    """Recognize a command-position ``[[`` without rescanning the full input."""

    segment_start = position
    while (
        segment_start > 0
        and command[segment_start - 1] not in ";&|(`\n\r"
    ):
        segment_start -= 1
    if segment_start > 0:
        segment_start -= 1
    return (
        _CONDITIONAL_OPEN_AT_END.search(
            command,
            segment_start,
            position + 2,
        )
        is not None
    )


def _array_assignment_opens_at(command: str, position: int) -> bool:
    """Recognize the no-whitespace ``name=(`` array-assignment form."""

    word_start = position
    while (
        word_start > 0
        and command[word_start - 1] not in " \t\r\n;&|"
    ):
        word_start -= 1
    return (
        _ARRAY_ASSIGNMENT_AT_END.fullmatch(command, word_start, position)
        is not None
    )


@lru_cache(maxsize=128)
def _shell_context_map(command: str) -> tuple[int, ...]:
    """Build shell-context classifications for every character in one pass."""

    contexts = [_LITERAL_CONTEXT] * (len(command) + 1)
    # Entries are (context, parenthesis_depth, at_word_start). Quote contexts
    # return to the previous executable context when popped.
    stack: list[tuple[str, int, bool]] = [("normal", 0, True)]
    command_substitution_opens: dict[int, int] = {}
    command_substitution_closes: dict[int, int | None] = {}
    command_substitution_case_closes: dict[int, frozenset[int]] = {}
    pending_heredocs: list[tuple[str, bool, bool]] = []
    case_head_ends = tuple(match.end() for match in _CASE_HEAD.finditer(command))
    index = 0

    def push_command_substitution(open_position: int) -> None:
        stack.append(("command_substitution", 1, True))
        command_substitution_opens[len(stack) - 1] = open_position

    def pop_command_substitution(frame_index: int) -> None:
        command_substitution_opens.pop(frame_index, None)
        command_substitution_closes.pop(frame_index, None)
        command_substitution_case_closes.pop(frame_index, None)
        stack.pop()

    def substitution_prefix_has_case(
        open_position: int,
        close_candidate: int,
    ) -> bool:
        low = 0
        high = len(case_head_ends)
        while low < high:
            middle = (low + high) // 2
            if case_head_ends[middle] <= close_candidate + 1:
                low = middle + 1
            else:
                high = middle
        return low > 0 and case_head_ends[low - 1] > open_position + 1

    while index < len(command):
        context, depth, at_word_start = stack[-1]
        executable = context in _EXECUTABLE_CONTEXTS
        contexts[index] = (
            _EXECUTABLE_CONTEXT if executable else _LITERAL_CONTEXT
        )
        char = command[index]
        following = command[index + 1] if index + 1 < len(command) else ""

        if context == "single":
            if char == "'":
                stack.pop()
            index += 1
            continue

        if context == "ansi_c_single":
            if char == "\\" and following:
                index += 2
                continue
            if char == "'":
                stack.pop()
            index += 1
            continue

        if context == "double":
            if char == "\\" and following in {'$', '`', '"', "\\", "\n", "\r"}:
                contexts[index + 1] = (
                    _LINE_CONTINUATION
                    if following in {"\n", "\r"}
                    else _LITERAL_CONTEXT
                )
                index += 2
                if (
                    following == "\r"
                    and index < len(command)
                    and command[index] == "\n"
                ):
                    contexts[index] = _LINE_CONTINUATION
                    index += 1
                continue
            if char == '"':
                stack.pop()
                index += 1
                continue
            if _PROMPT_TRANSFORM.match(command, index):
                contexts[index] = _EXECUTABLE_CONTEXT
            if char == "$" and following == "{":
                contexts[index + 1] = _LITERAL_CONTEXT
                stack.append(("parameter", 1, False))
                index += 2
                continue
            if char == "$" and following == "(":
                if index + 2 < len(command) and command[index + 2] == "(":
                    contexts[index + 1] = _LITERAL_CONTEXT
                    contexts[index + 2] = _LITERAL_CONTEXT
                    stack.append(("arithmetic", 2, False))
                    index += 3
                else:
                    contexts[index + 1] = _EXECUTABLE_CONTEXT
                    push_command_substitution(index + 1)
                    index += 2
                continue
            if char == "`":
                contexts[index] = _EXECUTABLE_CONTEXT
                stack.append(("backtick", 0, True))
                index += 1
                continue
            index += 1
            continue

        if context == "arithmetic":
            if char == "\\" and following:
                index += 2
                continue
            if _PROMPT_TRANSFORM.match(command, index):
                contexts[index] = _EXECUTABLE_CONTEXT
            if char == "$" and following == "{":
                contexts[index + 1] = _LITERAL_CONTEXT
                stack.append(("parameter", 1, False))
                index += 2
                continue
            if char == "$" and following == "(":
                if index + 2 < len(command) and command[index + 2] == "(":
                    contexts[index + 1] = _LITERAL_CONTEXT
                    contexts[index + 2] = _LITERAL_CONTEXT
                    stack.append(("arithmetic", 2, False))
                    index += 3
                else:
                    contexts[index + 1] = _EXECUTABLE_CONTEXT
                    push_command_substitution(index + 1)
                    index += 2
                continue
            if char == "`":
                contexts[index] = _EXECUTABLE_CONTEXT
                stack.append(("backtick", 0, True))
                index += 1
                continue
            if char == "(":
                stack[-1] = (context, depth + 1, False)
            elif char == ")":
                if depth == 1:
                    stack.pop()
                else:
                    stack[-1] = (context, depth - 1, False)
            index += 1
            continue

        if context == "parameter":
            if char == "\\" and following:
                index += 2
                continue
            if _PROMPT_TRANSFORM.match(command, index):
                contexts[index] = _EXECUTABLE_CONTEXT
            if char == "$" and following == "{":
                contexts[index + 1] = _LITERAL_CONTEXT
                stack[-1] = (context, depth + 1, False)
                index += 2
                continue
            if char == "$" and following == "'":
                stack.append(("ansi_c_single", 0, False))
                index += 2
                continue
            if char == "'":
                stack.append(("single", 0, False))
                index += 1
                continue
            if char == '"':
                stack.append(("double", 0, False))
                index += 1
                continue
            if char == "$" and following == "(":
                if index + 2 < len(command) and command[index + 2] == "(":
                    contexts[index + 1] = _LITERAL_CONTEXT
                    contexts[index + 2] = _LITERAL_CONTEXT
                    stack.append(("arithmetic", 2, False))
                    index += 3
                else:
                    contexts[index + 1] = _EXECUTABLE_CONTEXT
                    push_command_substitution(index + 1)
                    index += 2
                continue
            if char == "`":
                contexts[index] = _EXECUTABLE_CONTEXT
                stack.append(("backtick", 0, True))
                index += 1
                continue
            if char == "}":
                if depth == 1:
                    stack.pop()
                else:
                    stack[-1] = (context, depth - 1, False)
            index += 1
            continue

        if context in {"array", "conditional"}:
            if char == "\\" and following:
                index += 2
                continue
            if context == "conditional" and char == "]" and following == "]":
                contexts[index + 1] = _LITERAL_CONTEXT
                stack.pop()
                index += 2
                continue
            if _PROMPT_TRANSFORM.match(command, index):
                contexts[index] = _EXECUTABLE_CONTEXT
            if char == "$" and following == "{":
                contexts[index + 1] = _LITERAL_CONTEXT
                stack.append(("parameter", 1, False))
                index += 2
                continue
            if char == "$" and following == "'":
                stack.append(("ansi_c_single", 0, False))
                index += 2
                continue
            if char == "'":
                stack.append(("single", 0, False))
                index += 1
                continue
            if char == '"':
                stack.append(("double", 0, False))
                index += 1
                continue
            if char == "`":
                contexts[index] = _EXECUTABLE_CONTEXT
                stack.append(("backtick", 0, True))
                index += 1
                continue
            if char == "$" and following == "(":
                if index + 2 < len(command) and command[index + 2] == "(":
                    contexts[index + 1] = _LITERAL_CONTEXT
                    contexts[index + 2] = _LITERAL_CONTEXT
                    stack.append(("arithmetic", 2, False))
                    index += 3
                else:
                    contexts[index + 1] = _EXECUTABLE_CONTEXT
                    push_command_substitution(index + 1)
                    index += 2
                continue
            if char in "<>" and following == "(":
                contexts[index + 1] = _EXECUTABLE_CONTEXT
                push_command_substitution(index + 1)
                index += 2
                continue
            if context == "array":
                if char == "(":
                    stack[-1] = (context, depth + 1, False)
                elif char == ")":
                    if depth == 1:
                        stack.pop()
                    else:
                        stack[-1] = (context, depth - 1, False)
            index += 1
            continue

        # normal, command substitution, and backtick bodies are executable
        # shell contexts. Quotes nested inside them are literal until closed.
        if char == "\\" and following:
            contexts[index + 1] = (
                _LINE_CONTINUATION
                if following in {"\n", "\r"}
                else _LITERAL_CONTEXT
            )
            if following not in {"\n", "\r"}:
                stack[-1] = (context, depth, False)
            index += 2
            if (
                following == "\r"
                and index < len(command)
                and command[index] == "\n"
            ):
                contexts[index] = _LINE_CONTINUATION
                index += 1
            continue
        if context == "backtick" and char == "`":
            stack.pop()
            index += 1
            continue
        if char == "#" and at_word_start:
            line_end, _ = _line_break(command, index)
            contexts[index:line_end] = [_LITERAL_CONTEXT] * (line_end - index)
            index = line_end
            continue
        if char in "\r\n" and pending_heredocs:
            ranges, resume = _heredoc_ranges(command, index, pending_heredocs)
            for start, end, quoted, terminated in ranges:
                contexts[start:end] = [_LITERAL_CONTEXT] * (end - start)
                if not quoted:
                    _mark_unquoted_heredoc_continuations(
                        command,
                        start,
                        end,
                        contexts,
                    )
                    _mark_unquoted_heredoc_expansions(
                        command,
                        start,
                        end,
                        contexts,
                        terminated=terminated,
                    )
            pending_heredocs.clear()
            index = resume
            continue
        if char == "<" and following == "<":
            heredoc = _parse_heredoc(command, index)
            if heredoc is not None:
                delimiter, strip_tabs, quoted, end_position = heredoc
                pending_heredocs.append((delimiter, strip_tabs, quoted))
                stack[-1] = (context, depth, False)
                index = end_position
                continue
        if (
            char == "["
            and following == "["
            and _conditional_opens_at(command, index)
        ):
            contexts[index] = _LITERAL_CONTEXT
            contexts[index + 1] = _LITERAL_CONTEXT
            stack[-1] = (context, depth, False)
            stack.append(("conditional", 0, False))
            index += 2
            continue
        if char == "$" and following == "{":
            stack[-1] = (context, depth, False)
            contexts[index + 1] = _LITERAL_CONTEXT
            stack.append(("parameter", 1, False))
            index += 2
            continue
        if char == "$" and following == "'":
            stack[-1] = (context, depth, False)
            stack.append(("ansi_c_single", 0, False))
            index += 2
            continue
        if char == "'":
            stack[-1] = (context, depth, False)
            stack.append(("single", 0, False))
            index += 1
            continue
        if char == '"':
            stack[-1] = (context, depth, False)
            stack.append(("double", 0, False))
            index += 1
            continue
        if char == "`":
            stack[-1] = (context, depth, False)
            stack.append(("backtick", 0, True))
            index += 1
            continue
        if char == "$" and following == "(":
            stack[-1] = (context, depth, False)
            if index + 2 < len(command) and command[index + 2] == "(":
                contexts[index + 1] = _LITERAL_CONTEXT
                contexts[index + 2] = _LITERAL_CONTEXT
                stack.append(("arithmetic", 2, False))
                index += 3
            else:
                contexts[index + 1] = _EXECUTABLE_CONTEXT
                push_command_substitution(index + 1)
                index += 2
            continue
        if char == "(" and _array_assignment_opens_at(command, index):
            contexts[index] = _LITERAL_CONTEXT
            stack[-1] = (context, depth, False)
            stack.append(("array", 1, False))
            index += 1
            continue
        if char == "(" and following == "(":
            contexts[index + 1] = _LITERAL_CONTEXT
            stack[-1] = (context, depth, False)
            stack.append(("arithmetic", 2, False))
            index += 2
            continue
        if context == "command_substitution":
            if char == "(":
                stack[-1] = (context, depth + 1, True)
            elif char == ")":
                frame_index = len(stack) - 1
                expected_close = command_substitution_closes.get(frame_index)
                case_closes = command_substitution_case_closes.get(
                    frame_index,
                    frozenset(),
                )
                if expected_close is None:
                    open_position = command_substitution_opens[frame_index]
                    if substitution_prefix_has_case(open_position, index):
                        body_start = open_position + 1
                        body = command[body_start:]
                        case_closes = frozenset(
                            body_start + position
                            for position in _bounded_case_pattern_close_positions(
                                body
                            )
                        )
                        if index in case_closes:
                            command_substitution_case_closes[frame_index] = (
                                case_closes
                            )
                            expected_close = _command_substitution_close(
                                command,
                                open_position,
                                len(command),
                            )
                            command_substitution_closes[frame_index] = (
                                expected_close
                            )
                if index in case_closes:
                    stack[-1] = (context, depth, True)
                elif expected_close == index:
                    pop_command_substitution(frame_index)
                elif expected_close is not None:
                    if depth > 1:
                        stack[-1] = (context, depth - 1, False)
                elif depth == 1:
                    pop_command_substitution(frame_index)
                else:
                    stack[-1] = (context, depth - 1, False)
            elif char.isspace() or char in ";&|<>":
                stack[-1] = (context, depth, True)
            else:
                stack[-1] = (context, depth, False)
        elif char.isspace() or char in ";&|()<>":
            stack[-1] = (context, depth, True)
        else:
            stack[-1] = (context, depth, False)
        index += 1

    context = stack[-1][0]
    contexts[len(command)] = (
        _EXECUTABLE_CONTEXT
        if context in _EXECUTABLE_CONTEXTS
        else _LITERAL_CONTEXT
    )
    return tuple(contexts)


def _shell_context_is_executable(command: str, position: int) -> bool | None:
    """Classify ``position`` as executable, literal, or line-continuation."""

    position = max(0, min(position, len(command)))
    context = _shell_context_map(command)[position]
    if context == _LINE_CONTINUATION:
        return None
    return context == _EXECUTABLE_CONTEXT


def _has_executable_match(pattern: re.Pattern[str], command: str) -> bool:
    search_position = 0
    while match := pattern.search(command, search_position):
        context = _shell_context_is_executable(command, match.start())
        if context is True:
            return True
        if context is None:
            marker = match.start()
            end = marker + 1
            if (
                marker < len(command)
                and command[marker] == "\r"
                and end < len(command)
                and command[end] == "\n"
            ):
                end += 1
            collapsed = command[: marker - 1] + command[end:]
            if _has_executable_match(pattern, collapsed):
                return True
        # A pattern such as ``sh -c '<body>'`` may greedily span from an inert
        # quoted occurrence across a later real invocation. Resume one
        # character after the rejected start so overlapping candidates remain
        # visible instead of advancing to the greedy match's end.
        search_position = match.start() + 1
    return False


def _collapse_line_continuations(command: str) -> str:
    """Remove active backslash-newline pairs before regex matching."""

    contexts = _shell_context_map(command)
    collapsed: list[str] = []
    index = 0
    while index < len(command):
        if (
            command[index] == "\\"
            and index + 1 < len(command)
            and contexts[index + 1] == _LINE_CONTINUATION
        ):
            index += 2
            if (
                index < len(command)
                and command[index - 1] == "\r"
                and command[index] == "\n"
            ):
                index += 1
            continue
        collapsed.append(command[index])
        index += 1
    return "".join(collapsed)


def _eval_argument_tail(command: str, start: int) -> str:
    """Return the outer-shell argument text following an ``eval`` command."""

    stack: list[tuple[str, int, bool]] = [("normal", 0, True)]
    index = start
    while index < len(command):
        context, depth, at_word_start = stack[-1]
        char = command[index]
        following = command[index + 1] if index + 1 < len(command) else ""

        if context == "single":
            if char == "'":
                stack.pop()
            index += 1
            continue
        if context == "ansi_c_single":
            if char == "\\" and following:
                index += 2
                continue
            if char == "'":
                stack.pop()
            index += 1
            continue
        if context == "double":
            if char == "\\" and following in {'$', '`', '"', "\\", "\n", "\r"}:
                index += 2
                continue
            if char == '"':
                stack.pop()
                index += 1
                continue
            if char == "$" and following == "(":
                stack.append(("command_substitution", 1, True))
                index += 2
                continue
            if char == "`":
                stack.append(("backtick", 0, True))
                index += 1
                continue
            index += 1
            continue

        if char == "\\" and following:
            stack[-1] = (context, depth, False)
            index += 2
            continue
        if context == "backtick" and char == "`":
            stack.pop()
            index += 1
            continue
        if len(stack) == 1:
            if char in ";&|\r\n)" or (char == "#" and at_word_start):
                break
        if char == "$" and following == "'":
            stack[-1] = (context, depth, False)
            stack.append(("ansi_c_single", 0, False))
            index += 2
            continue
        if char == "'":
            stack[-1] = (context, depth, False)
            stack.append(("single", 0, False))
            index += 1
            continue
        if char == '"':
            stack[-1] = (context, depth, False)
            stack.append(("double", 0, False))
            index += 1
            continue
        if char == "`":
            stack[-1] = (context, depth, False)
            stack.append(("backtick", 0, True))
            index += 1
            continue
        if char == "$" and following == "(":
            stack[-1] = (context, depth, False)
            stack.append(("command_substitution", 1, True))
            index += 2
            continue
        if context == "command_substitution":
            if char == "(":
                stack[-1] = (context, depth + 1, True)
            elif char == ")":
                if depth == 1:
                    stack.pop()
                else:
                    stack[-1] = (context, depth - 1, False)
            elif char.isspace() or char in ";&|<>":
                stack[-1] = (context, depth, True)
            else:
                stack[-1] = (context, depth, False)
        elif char.isspace() or char in "<>":
            stack[-1] = (context, depth, True)
        else:
            stack[-1] = (context, depth, False)
        index += 1

    return command[start:index]


def _normalize_ansi_c_quotes(raw_body: str) -> str | None:
    """Rewrite active ``$'...'`` segments into POSIX-shlex-safe quoting."""

    normalized: list[str] = []
    context = "normal"
    index = 0
    while index < len(raw_body):
        char = raw_body[index]
        following = raw_body[index + 1] if index + 1 < len(raw_body) else ""
        if context == "single":
            normalized.append(char)
            if char == "'":
                context = "normal"
            index += 1
            continue
        if context == "double":
            normalized.append(char)
            if char == "\\" and following:
                normalized.append(following)
                index += 2
                continue
            if char == '"':
                context = "normal"
            index += 1
            continue

        if char == "\\" and following:
            normalized.extend((char, following))
            index += 2
            continue
        if char == "'":
            normalized.append(char)
            context = "single"
            index += 1
            continue
        if char == '"':
            normalized.append(char)
            context = "double"
            index += 1
            continue
        if char == "$" and following == "'":
            cursor = index + 2
            encoded: list[str] = []
            while cursor < len(raw_body):
                if raw_body[cursor] == "\\" and cursor + 1 < len(raw_body):
                    encoded.extend((raw_body[cursor], raw_body[cursor + 1]))
                    cursor += 2
                    continue
                if raw_body[cursor] == "'":
                    break
                encoded.append(raw_body[cursor])
                cursor += 1
            if cursor >= len(raw_body):
                return None
            decoded = _decode_ansi_c_string("".join(encoded))
            if decoded is None:
                return None
            normalized.append(shlex.quote(decoded))
            index = cursor + 1
            continue
        normalized.append(char)
        index += 1
    return "".join(normalized)


def _decode_shell_words(raw_body: str) -> list[str]:
    normalized = _normalize_ansi_c_quotes(raw_body)
    shell_text = raw_body if normalized is None else normalized
    try:
        words = shlex.split(shell_text, comments=False, posix=True)
    except ValueError:
        return [raw_body]
    if '$"' in raw_body:
        words = [word[1:] if word.startswith("$") else word for word in words]
    return words


def _executable_basename(raw_word: str) -> str | None:
    """Normalize a command-head word to its executable basename.

    Resolves bare names, absolute/relative path prefixes, and quoted forms the
    bounded decoder already understands. Returns ``None`` when the word is not
    a concrete executable token.

    Also strips shell redirections glued to the head (``omc>out``,
    ``omg</dev/null``, ``{fd}>/dev/null``): real shells tokenize those as
    executable + redir, but ``_SHELL_WORD`` keeps ``<``/``>`` inside the match.
    Linear quote-aware boundary insert + first-token basename; trailing redir
    noise is ignored.
    """

    if not raw_word:
        return None
    # Split glued redirs (and any other unquoted shell ops) before shlex so
    # basename is the executable, not ``omc>out`` / path ending in ``null``.
    normalized = _insert_unquoted_shell_boundaries(raw_word)
    words = _decode_shell_words(normalized)
    if not words:
        return None
    first = words[0]
    if not first or first in _SHELL_COMMAND_SEPARATORS or first in ("(", ")"):
        return None
    if _is_shell_redirect_token(first):
        return None
    base = first.rsplit("/", 1)[-1].lower()
    return base or None


def _decoded_shell_word_is_denied(raw_word: str) -> bool:
    executable = _executable_basename(raw_word)
    return executable in _DENIED_BIN_NAMES if executable else False


def _starts_shell_expansion(char: str) -> bool:
    return bool(
        char
        and (
            char.isalnum()
            or char == "_"
            or char in "({*@#?$!-"
        )
    )


def _shell_word_has_dynamic_expansion(command: str, start: int = 0) -> bool:
    """Return whether one shell word contains an active runtime expansion."""

    index = start
    while index < len(command) and command[index].isspace():
        index += 1
    context = "normal"
    while index < len(command):
        char = command[index]
        following = command[index + 1] if index + 1 < len(command) else ""
        if context == "single":
            if char == "'":
                context = "normal"
            index += 1
            continue
        if context == "ansi_c_single":
            if char == "\\" and following:
                index += 2
                continue
            if char == "'":
                context = "normal"
            index += 1
            continue
        if context == "double":
            if char == "\\" and following in {'$', '`', '"', "\\", "\r", "\n"}:
                index += 2
                if (
                    following == "\r"
                    and index < len(command)
                    and command[index] == "\n"
                ):
                    index += 1
                continue
            if char == '"':
                context = "normal"
                index += 1
                continue
            if char == "`" or (
                char == "$" and _starts_shell_expansion(following)
            ):
                return True
            index += 1
            continue

        if char.isspace() or char in ";&|()<>":
            return False
        if char == "\\" and following:
            index += 2
            continue
        if char == "$" and following == "'":
            context = "ansi_c_single"
            index += 2
            continue
        if char == "$" and following == '"':
            # Locale translation can alter a command word at runtime.
            return True
        if char == "'":
            context = "single"
            index += 1
            continue
        if char == '"':
            context = "double"
            index += 1
            continue
        if char == "`" or (
            char == "$" and _starts_shell_expansion(following)
        ):
            return True
        index += 1
    return False


def _has_dynamic_command_head(command: str) -> bool:
    """Fail closed when an executable word is synthesized at runtime."""

    search_position = 0
    while match := _DYNAMIC_COMMAND_PREFIX.search(command, search_position):
        if (
            _shell_context_is_executable(command, match.start()) is True
            and _shell_word_has_dynamic_expansion(command, match.end())
        ):
            return True
        search_position = match.start() + 1
    return False


def _has_denied_decoded_command_head(command: str) -> bool:
    """Deny quoted or concatenated spellings of a blocked executable word."""

    search_position = 0
    while match := _DECODED_COMMAND_HEAD.search(command, search_position):
        if _shell_context_is_executable(command, match.start()) is True:
            raw_word = match.group("word")
            if _decoded_shell_word_is_denied(raw_word):
                return True
            base = _executable_basename(raw_word)
            if _should_peel_wrapper_head(raw_word, base):
                words = _semantic_words_from_head_match(command, match, limit=8)
                remaining = _peel_wrapper_chain(words)
                if remaining and _decoded_shell_word_is_denied(remaining[0]):
                    return True
        search_position = match.start() + 1
    return False


# Bound how much trailing text we decode after a matched executable head when
# classifying ``omc team`` / ``omg team`` — avoids O(n²) shlex on huge scripts.
_HEAD_TAIL_DECODE_LIMIT = 512
# Max raw tokens examined after boundary insert while dropping redirects. The
# char-bounded fragment is already small; this is a secondary safety cap so a
# pathological token soup cannot stall the hook. Must stay large enough that
# several FD redirects (``0</dev/null 1>out 2>&1`` → ~9 raw words) never starve
# the semantic ``team`` / op tokens (Codex review3 multi-redir Critical).
_HEAD_TAIL_RAW_SCAN_CAP = 64

# Pure command separators / pipeline control — stop argv collection for the
# current head (do not glue the next shell command into this argv).
# ``\n``/``\r`` are listed for documentation; unquoted newlines are rewritten
# to ``;`` in :func:`_insert_unquoted_shell_boundaries` because ``shlex`` treats
# newlines as whitespace and would otherwise erase the command boundary.
_SHELL_COMMAND_SEPARATORS = frozenset({";", "&", "&&", "|", "||", "\n", "\r"})
# Pure redirection operators that take a following word as the target when
# not already glued (``> out`` vs ``>out``).
_SHELL_REDIR_OPS = frozenset(
    {">", ">>", "<", "<<", "<>", "<<<", ">&", "<&", ">|", "&>", "&>>"}
)
# Glued target (``2>/dev/null``) stays digit-or-empty prefix only. A quoted
# ``'{fd}>/dev/null'`` decodes to one argv word and must remain literal.
_SHELL_REDIR_GLUED = re.compile(
    r"^(?:\d*)(?:<<<|>>|<<|<>|>&|<&|>\||&>|&>>|[<>]).+"
)
_SHELL_REDIR_PURE = re.compile(
    rf"^{_REDIR_FD_PREFIX}(?:<<<|>>|<<|<>|>&|<&|>\||&>|&>>|[<>])$"
)
# Redirection operators that may take an adjacent FD prefix (``2>``,
# ``2>&``, ``2<>``, ``{fd}>``, ``{fd}>&``). Control operators ``&&`` / ``||``
# are not included.
_SHELL_REDIR_TWOCHAR = frozenset({">>", "<<", "<>", ">&", "<&", ">|", "&>"})


# Shell allows multi-digit FDs; keep a hard upper bound only as DoS guard
# (old arbitrary 4-digit cap false-negatived ``12345>/dev/null …``).
_MAX_ADJACENT_FD_DIGITS = 64
# Bash 4+ named FD ``{ident}`` — ident is ``[A-Za-z_][A-Za-z0-9_]*``, max 64.
_MAX_NAMED_FD_IDENT = 64


def _adjacent_named_fd_prefix(text: str, op_index: int) -> str:
    """Return adjacent ``{ident}`` immediately before *op_index*, else ``""``.

    Fail-closed bash 4+ named-FD syntax: unquoted ``{fd}>word`` is one
    redirect unit (on bash 3.2 it is argv ``{fd}`` plus ``>``, but the
    command is still ``omc … team``). Rejects empty ``{}``, digit-leading
    ``{1fd}``, hyphen ``{fd-x}``, idents longer than
    :data:`_MAX_NAMED_FD_IDENT`, and ``{ident}`` glued to an alnum/``_``
    head (``omc{fd}>out``).
    """

    if op_index < 2 or text[op_index - 1] != "}":
        return ""
    ident_end = op_index - 1
    cursor = ident_end - 1
    while cursor >= 0 and (
        "A" <= text[cursor] <= "Z"
        or "a" <= text[cursor] <= "z"
        or "0" <= text[cursor] <= "9"
        or text[cursor] == "_"
    ):
        if ident_end - cursor > _MAX_NAMED_FD_IDENT:
            return ""
        cursor -= 1
    if cursor < 0 or text[cursor] != "{":
        return ""
    ident = text[cursor + 1 : ident_end]
    if not ident or len(ident) > _MAX_NAMED_FD_IDENT:
        return ""
    first = ident[0]
    if not (("A" <= first <= "Z") or ("a" <= first <= "z") or first == "_"):
        return ""
    if cursor > 0:
        before = text[cursor - 1]
        if before.isalnum() or before == "_":
            return ""
    return text[cursor:op_index]


def _adjacent_fd_prefix(text: str, op_index: int) -> str:
    """Return adjacent FD prefix immediately before *op_index*, else ``""``.

    Digit FDs (``2>out`` / ``12345>/dev/null``) and bash named FDs
    (``{fd}>`` / ``{my_fd}>>``) stay one redirect token when unquoted and
    adjacent. Spaced ``2 >out`` / ``{fd} >out`` remain argv + redirect.
    A prefix glued to an alnum/``_`` head (``echo2>out``, ``omc{fd}>out``)
    is not an FD. Digit length is accepted up to
    :data:`_MAX_ADJACENT_FD_DIGITS`; named idents up to
    :data:`_MAX_NAMED_FD_IDENT`.
    """

    if op_index <= 0:
        return ""
    start = op_index
    while (
        start > 0
        and text[start - 1].isdigit()
        and op_index - (start - 1) <= _MAX_ADJACENT_FD_DIGITS
    ):
        start -= 1
    digits = text[start:op_index]
    if digits and digits.isdecimal():
        if start > 0:
            before = text[start - 1]
            if before.isalnum() or before == "_":
                return ""
        return digits
    return _adjacent_named_fd_prefix(text, op_index)


def _emit_redir_op(out: list[str], text: str, op_index: int, op_len: int) -> None:
    """Append a spaced redir token, gluing an immediately-adjacent FD prefix.

    Pops already-emitted prefix characters from *out* when they form a bare
    digit FD or named FD ``{ident}`` that was adjacent to the operator in the
    original text. Spaced forms such as ``2 >out`` / ``{fd} >out`` keep the
    prefix as a normal argv word.
    """

    fd = _adjacent_fd_prefix(text, op_index)
    op = text[op_index : op_index + op_len]
    if fd and len(out) >= len(fd) and "".join(out[-len(fd) :]) == fd:
        del out[-len(fd) :]
        out.append(f" {fd}{op} ")
    else:
        out.append(f" {op} ")


def _insert_unquoted_shell_boundaries(text: str) -> str:
    """Insert whitespace around unquoted shell operators (linear, quote-aware).

    ``shlex`` does not treat ``; | & < > ( )`` as token boundaries when they are
    glued to a word (``team>out``, ``team;echo``). Real shells do. This pass
    normalizes only the bounded tail after an executable head so both foreign
    ``omc team`` and first-party nested classification see the same tokens.

    Also:
    - Keeps FD digits **and** named FDs **adjacent** to redirection ops
      (``2>out`` → ``2>`` + target, ``{fd}>/dev/null`` → ``{fd}>`` + target)
      so spaced ``2 >out`` / ``{fd} >out`` remain argv + redirect (review3).
    - Rewrites unquoted newlines/CRs to ``;`` so ``shlex`` cannot erase command
      separators (``omc>out\\nteam`` is two commands, not ``omc team``).

    Preserves single/double quotes and backslash escapes. Does not expand
    substitutions or implement full shell grammar. O(n) in *text* length.
    """

    if not text:
        return text
    out: list[str] = []
    context = "normal"  # normal | single | double
    index = 0
    n = len(text)
    while index < n:
        char = text[index]
        following = text[index + 1] if index + 1 < n else ""
        if context == "single":
            out.append(char)
            if char == "'":
                context = "normal"
            index += 1
            continue
        if context == "double":
            out.append(char)
            if char == "\\" and following:
                out.append(following)
                index += 2
                continue
            if char == '"':
                context = "normal"
            index += 1
            continue
        # normal context
        if char == "\\" and following:
            out.extend((char, following))
            index += 2
            continue
        if char == "'":
            out.append(char)
            context = "single"
            index += 1
            continue
        if char == '"':
            out.append(char)
            context = "double"
            index += 1
            continue
        # Unquoted newline / CR are command separators. ``shlex`` treats them as
        # whitespace and would otherwise glue the next line's tokens into this
        # head's argv (``omc>out\\nteam`` must not become ``omc`` + ``team``).
        if char == "\r":
            index += 2 if following == "\n" else 1
            out.append(" ; ")
            continue
        if char == "\n":
            out.append(" ; ")
            index += 1
            continue
        # Multi-character operators first (longest match).
        three = text[index : index + 3]
        if three in ("&>>", "<<<"):
            _emit_redir_op(out, text, index, 3)
            index += 3
            continue
        two = char + following if following else char
        if two in ("&&", "||"):
            out.append(f" {two} ")
            index += 2
            continue
        if two in _SHELL_REDIR_TWOCHAR:
            _emit_redir_op(out, text, index, 2)
            index += 2
            continue
        if char in "<>":
            _emit_redir_op(out, text, index, 1)
            index += 1
            continue
        if char in ";&|()":
            out.append(f" {char} ")
            index += 1
            continue
        out.append(char)
        index += 1
    return "".join(out)


def _is_shell_redirect_token(word: str) -> bool:
    """True for pure or glued redirection tokens (not ordinary path args).

    Includes digit-prefixed (``2>``, ``2>/dev/null``) and named-FD
    (``{fd}>``, ``{fd}>/dev/null``) forms.
    """

    if not word:
        return False
    if word in _SHELL_REDIR_OPS:
        return True
    if _SHELL_REDIR_PURE.match(word):
        return True
    if _SHELL_REDIR_GLUED.match(word):
        return True
    return False


def _next_decoded_words(
    command: str,
    start: int,
    *,
    limit: int = 4,
    raise_on_budget: bool = False,
) -> list[str]:
    """Decode at most *limit* **semantic** argv words from a bounded tail.

    Applies a linear shell-operator boundary correction before shlex so
    no-space forms like ``team>out`` / ``team;echo`` still yield ``team`` as
    the first word. Shared by foreign ``omc team`` and first-party nested
    classification.

    Skips redirections *between* the executable and later argv (``omc 2>out
    team``, ``omg 0</dev/null 1>out 2>&1 team``, ``omc <>out team``,
    ``omc <<<payload team``, ``omc {fd}>/dev/null team``). FD-prefixed
    redirs stay a single redirect token when originally adjacent
    (``2>out``, ``2<>out``, ``{fd}>``, ``{fd}>&``); a spaced numeric or
    ``{ident}`` argv (``2 >out``, ``{fd} >out``) remains a semantic word.
    Raw tokens are **not** truncated before redirect-dropping — only the
    512-char fragment bound and :data:`_HEAD_TAIL_RAW_SCAN_CAP` apply — so
    multi-redir sequences cannot starve ``team``.

    When *raise_on_budget* is true, character or raw-token budget exhaustion
    before a separator or *limit* semantic words raises
    :class:`_ShellParseBudgetExceeded` (indeterminate). Callers must enable
    that only for orchestrator / nested-Team candidates.
    """

    if start >= len(command):
        return []
    char_truncated = start + _HEAD_TAIL_DECODE_LIMIT < len(command)
    end = min(len(command), start + _HEAD_TAIL_DECODE_LIMIT)
    fragment = _insert_unquoted_shell_boundaries(command[start:end])
    # Decode the whole bounded fragment; drop redirs while scanning so a long
    # redirect sequence never cuts ``team`` off before semantic collection.
    raw_words = _decode_shell_words(fragment)
    token_truncated = len(raw_words) > _HEAD_TAIL_RAW_SCAN_CAP
    semantic: list[str] = []
    skip_next = False
    index = 0
    n_raw = min(len(raw_words), _HEAD_TAIL_RAW_SCAN_CAP)
    hit_separator = False
    while index < n_raw:
        word = raw_words[index]
        index += 1
        if skip_next:
            skip_next = False
            continue
        if word in _SHELL_COMMAND_SEPARATORS:
            hit_separator = True
            break
        if word in ("(", ")"):
            hit_separator = True
            break
        if _is_shell_redirect_token(word):
            # Pure ops (``>``, ``2>``, ``{fd}>``, ``<>``, ``<<<``, ``>&``)
            # take a following target. Glued forms already include the target.
            if word in _SHELL_REDIR_OPS or _SHELL_REDIR_PURE.match(word):
                skip_next = True
            continue
        semantic.append(word)
        if len(semantic) >= limit:
            break
    if (
        raise_on_budget
        and len(semantic) < limit
        and not hit_separator
        and (char_truncated or token_truncated)
    ):
        raise _ShellParseBudgetExceeded
    return semantic


def _token_basename(word: str) -> str:
    return word.rsplit("/", 1)[-1].lower() if word else ""


def _looks_like_wrapper_option_residue(token: str) -> bool:
    """True for a leftover wrapper flag used as the decoded command head."""

    return bool(token) and token.startswith("-")


def _should_peel_wrapper_head(raw_word: str, base: str | None) -> bool:
    """Peel when the captured head is a wrapper or a leftover option.

    Residue must be checked on the raw word first: ``env --split-string='…/usr/bin…'``
    makes ``_executable_basename`` take the path inside the option value, so a
    basename-only ``-…`` check would miss GNU ``--split-string=``.
    """

    return (
        _looks_like_wrapper_option_residue(raw_word)
        or _looks_like_wrapper_option_residue(base or "")
        or base in _WRAPPER_NAMES
    )


def _is_env_assign_token(token: str) -> bool:
    return bool(token) and _ENV_ASSIGN_TOKEN.match(token) is not None


def _glued_nice_adjustment(token: str) -> bool:
    """``-n5`` / ``-n-5`` — short niceness glued to ``-n``."""

    return token.startswith("-n") and _NICE_ADJ_TOKEN.match(token[2:]) is not None


def _command_option_kind(token: str) -> str | None:
    """Classify a POSIX ``command`` short option.

    ``discovery``: ``-v`` / ``-V`` or a ``p``/``v``/``V`` cluster that
    contains ``v`` or ``V`` (lookup; the following name is not executed).
    ``exec``: ``-p`` or a cluster of only ``p`` (default PATH, then execute).
    ``None``: not a recognized ``command`` option.
    """

    if len(token) < 2 or token[0] != "-" or token.startswith("--"):
        return None
    letters = token[1:]
    if not all(ch in "pvV" for ch in letters):
        return None
    if "v" in letters or "V" in letters:
        return "discovery"
    return "exec"


def _parse_env_split_string(raw: str) -> list[str] | None:
    """Bounded BSD/GNU ``env -S`` split. ``None`` is indeterminate (fail closed)."""

    if "${" in raw or len(raw) > _ENV_SPLIT_CHAR_CAP:
        return None
    tokens: list[str] = []
    buf: list[str] = []
    quote: str | None = None
    started = False
    index = 0
    length = len(raw)

    def flush() -> bool:
        nonlocal started
        if not started:
            return True
        if len(tokens) >= _ENV_SPLIT_TOKEN_CAP:
            return False
        tokens.append("".join(buf))
        buf.clear()
        started = False
        return True

    while index < length:
        char = raw[index]
        following = raw[index + 1] if index + 1 < length else ""
        if quote is None and char in " \t":
            if not flush():
                return None
            index += 1
            continue
        if quote is None and char == "#" and not started:
            break
        if quote is None and char.isspace():
            return None
        if char == "\\":
            if not following:
                return None
            if following == "c":
                if not flush():
                    return None
                return tokens
            if quote is None and following in {" ", "t", "_"}:
                if not flush():
                    return None
                index += 2
                continue
            if following in {"\\", "'", '"', "$", "#"}:
                buf.append(following)
                started = True
                index += 2
                continue
            if quote is not None and following in {" ", "t"}:
                buf.append(" " if following == " " else "\t")
                started = True
                index += 2
                continue
            return None
        if quote is None and char in {"'", '"'}:
            quote = char
            started = True
            index += 1
            continue
        if quote is not None and char == quote:
            quote = None
            index += 1
            continue
        if quote is None and char == "$":
            return None
        buf.append(char)
        started = True
        index += 1
    if quote is not None:
        return None
    if not flush():
        return None
    return tokens


def _peel_one_wrapper(words: list[str]) -> list[str] | None:
    """Peel one supported wrapper and its bounded options.

    Returns remaining words after the wrapper. Stops before an unknown or
    malformed option so the caller can fail-closed on residue flags.
    Returns ``None`` when *words* does not start with a wrapper name.
    ``env -S`` / ``--split-string`` expand once (fail closed if recursive
    or indeterminate). ``command -p`` is an execution wrapper;
    ``command -v`` / ``-V`` (and ``-pv`` clusters) are discovery and
    consume the rest of this invocation so the looked-up name is not a
    wrapped executable.
    """

    if not words:
        return None
    name = _token_basename(words[0])
    if name not in _WRAPPER_NAMES:
        return None
    index = 1
    n_words = len(words)
    split_used = False
    while index < n_words:
        token = words[index]
        if token == "--":
            index += 1
            break
        if name == "env":
            # One -S / --split-string per env wrapper. Splice in place; do
            # not skip the first expanded token so inner -i / NAME= still peel.
            split_raw: str | None = None
            split_extra = 0
            if token.startswith("-S=") or token.startswith("--S="):
                raise _ShellParseBudgetExceeded
            if token in {"-S", "--S", "--split-string"}:
                if index + 1 >= n_words:
                    raise _ShellParseBudgetExceeded
                split_raw = words[index + 1]
                split_extra = 1
            elif token.startswith("--split-string="):
                split_raw = token[len("--split-string=") :]
                if not split_raw:
                    raise _ShellParseBudgetExceeded
            elif _ENV_SPLIT_COMBINED_SHORT.fullmatch(token):
                if index + 1 >= n_words:
                    raise _ShellParseBudgetExceeded
                split_raw = words[index + 1]
                split_extra = 1
            elif token.startswith("-S") and len(token) > 2 and token[2] != "=":
                split_raw = token[2:]
            if split_raw is not None:
                if split_used:
                    raise _ShellParseBudgetExceeded
                split_used = True
                parsed = _parse_env_split_string(split_raw)
                if parsed is None:
                    raise _ShellParseBudgetExceeded
                words = words[:index] + parsed + words[index + 1 + split_extra :]
                n_words = len(words)
                continue
            if token in _ENV_WRAPPER_FLAGS:
                index += 1
                continue
            if token in _ENV_WRAPPER_VALUE_OPTS:
                if index + 1 >= n_words:
                    break
                index += 2
                continue
            if token.startswith(_ENV_WRAPPER_VALUE_EQ) and len(token) > len(
                _ENV_WRAPPER_VALUE_EQ
            ):
                index += 1
                continue
            if token.startswith(_ENV_WRAPPER_CHDIR_EQ) and len(token) > len(
                _ENV_WRAPPER_CHDIR_EQ
            ):
                index += 1
                continue
            if _is_env_assign_token(token):
                index += 1
                continue
            break
        if name == "command":
            kind = _command_option_kind(token)
            if kind == "discovery":
                # Lookup only: do not wrap the following name, and do not
                # leave ``-v`` for residue-skip to promote a deny-bin head.
                return []
            if kind == "exec":
                index += 1
                continue
            break
        if name == "nice":
            if _glued_nice_adjustment(token):
                index += 1
                continue
            if token in _NICE_WRAPPER_VALUE_OPTS:
                if index + 1 >= n_words or not _NICE_ADJ_TOKEN.match(words[index + 1]):
                    break
                index += 2
                continue
            if token.startswith(_NICE_WRAPPER_VALUE_EQ) and _NICE_ADJ_TOKEN.match(
                token[len(_NICE_WRAPPER_VALUE_EQ) :]
            ):
                index += 1
                continue
            break
        if name == "sudo":
            if token in _SUDO_WRAPPER_VALUE_OPTS:
                if index + 1 >= n_words:
                    break
                index += 2
                continue
            if token.startswith(_SUDO_WRAPPER_VALUE_EQ) and len(token) > len(
                _SUDO_WRAPPER_VALUE_EQ
            ):
                index += 1
                continue
            break
        if name == "xargs":
            if token in _XARGS_WRAPPER_VALUE_OPTS:
                if index + 1 >= n_words:
                    break
                index += 2
                continue
            if token.startswith(_XARGS_WRAPPER_VALUE_EQ) and len(token) > len(
                _XARGS_WRAPPER_VALUE_EQ
            ):
                index += 1
                continue
            break
        if name == "exec":
            if token in _EXEC_WRAPPER_VALUE_OPTS:
                if index + 1 >= n_words:
                    break
                index += 2
                continue
            if token in {"-c", "-l", "-cl", "-lc"}:
                index += 1
                continue
            break
        if _is_env_assign_token(token):
            index += 1
            continue
        break
    return words[index:]


def _peel_wrapper_chain(words: list[str]) -> list[str]:
    """Peel stacked supported wrappers, then skip leftover unknown flags."""

    remaining = words
    while remaining:
        peeled = _peel_one_wrapper(remaining)
        if peeled is None:
            break
        remaining = peeled
    return _after_wrapper_option_residue(remaining)


def _semantic_words_from_head_match(
    command: str,
    match: re.Match[str],
    *,
    limit: int,
    raise_on_budget: bool = False,
) -> list[str]:
    """Wrapper tokens in the match plus a bounded tail after the captured head.

    ``_WRAPPERS`` consumes only the wrapper *name*, so ``env -i omg`` captures
    ``-i``. Decoding the full match recovers ``env`` so option arity can peel.
    """

    raw = _decode_shell_words(_insert_unquoted_shell_boundaries(match.group(0)))
    cleaned: list[str] = []
    skip_next = False
    for word in raw:
        if skip_next:
            skip_next = False
            continue
        if word in _SHELL_COMMAND_SEPARATORS or word in ("(", ")"):
            continue
        if _is_shell_redirect_token(word):
            if word in _SHELL_REDIR_OPS or _SHELL_REDIR_PURE.match(word):
                skip_next = True
            continue
        cleaned.append(word)
    remain = max(0, limit - len(cleaned))
    if remain == 0:
        return cleaned
    tail = _next_decoded_words(
        command,
        match.end(),
        limit=remain,
        raise_on_budget=raise_on_budget,
    )
    return [*cleaned, *tail]


def _head_tail_budget_exhausted(command: str, match: re.Match[str]) -> bool:
    """Whether char or raw-token bounds ended before head resolution."""
    start = match.end()
    if start + _HEAD_TAIL_DECODE_LIMIT < len(command):
        return True
    fragment = _insert_unquoted_shell_boundaries(
        command[start : start + _HEAD_TAIL_DECODE_LIMIT]
    )
    return len(_decode_shell_words(fragment)) > _HEAD_TAIL_RAW_SCAN_CAP


def _after_wrapper_option_residue(words: list[str]) -> list[str]:
    """Skip leftover wrapper flags; return words from the first non-flag token.

    Fail-closed look-ahead only. Does not skip a following value token, so
    ``env --weird echo omg team`` does not treat later ``omg`` as the head.
    """

    if not words or not _looks_like_wrapper_option_residue(words[0]):
        return words
    index = 0
    while index < len(words) and _looks_like_wrapper_option_residue(words[index]):
        index += 1
    return words[index:]


def _shell_c_bodies_from_head_words(words: list[str]) -> list[str]:
    """If peeled wrappers leave ``sh|bash|zsh -c``, yield the command body."""

    remaining = _peel_wrapper_chain(words)
    if not remaining:
        return []
    bodies: list[str] = []
    if (
        _token_basename(remaining[0]) in {"sh", "bash", "zsh"}
        and len(remaining) >= 3
        and remaining[1].startswith("-")
        and "c" in remaining[1]
    ):
        bodies.append(remaining[2])
    return bodies


def _team_argv_from_semantic_words(words: list[str]) -> list[str] | None:
    """Return argv-after-``team`` after peeling wrappers / option residue.

    Unknown/malformed wrapper flags fail closed only when the next non-flag
    token is ``omg``. A non-flag head that is not ``omg`` is not scanned
    (avoids ``echo omg team``).
    """

    remaining = _peel_wrapper_chain(words)
    if not remaining:
        return None
    if _token_basename(remaining[0]) != _FIRST_PARTY_TEAM_BIN:
        return None
    rest = _peel_supported_team_leading_globals(remaining[1:])
    if rest and rest[0].lower() == "team":
        return [w.lower() for w in rest[1:]]
    return None


def _has_foreign_omc_team(command: str) -> bool:
    """True when a foreign ``omc team`` orchestration CLI is in command position.

    Covers bare, path-prefixed, wrapper (``env``/``command``/``exec``/…), and
    forms already exposed as executable heads by the bounded parser. Recursive
    ``sh|bash|zsh -c/-lc`` bodies are handled by the existing shell-c walk.
    Also covers no-space shell boundaries after *or before* ``team``
    (``omc team>out``, ``omc>out team``, ``omc 2>&1 team``,
    ``omc {fd}>/dev/null team``, ``omc team;echo``).
    Wrapper-option residue (``env --weird omc team``) fail-closes by scanning
    later tokens for ``omc`` + ``team``.
    """

    search_position = 0
    while match := _DECODED_COMMAND_HEAD.search(command, search_position):
        if _shell_context_is_executable(command, match.start()) is True:
            raw_word = match.group("word")
            base = _executable_basename(raw_word)
            if base in _FOREIGN_ORCHESTRATOR_BINS:
                tail = _next_decoded_words(
                    command, match.end(), limit=1, raise_on_budget=True
                )
                if tail and tail[0].lower() == "team":
                    return True
            elif _should_peel_wrapper_head(raw_word, base):
                words = _semantic_words_from_head_match(
                    command, match, limit=8, raise_on_budget=False
                )
                remaining = _peel_wrapper_chain(words)
                if (
                    remaining
                    and _token_basename(remaining[0])
                    in _FOREIGN_ORCHESTRATOR_BINS
                    and len(remaining) == 1
                    and _head_tail_budget_exhausted(command, match)
                ):
                    raise _ShellParseBudgetExceeded
                if (
                    remaining
                    and _token_basename(remaining[0]) in _FOREIGN_ORCHESTRATOR_BINS
                    and len(remaining) >= 2
                    and remaining[1].lower() == "team"
                ):
                    return True
        search_position = match.start() + 1
    return False


def _truthy_process_env(name: str) -> bool:
    return (os.environ.get(name) or "").strip().lower() in (
        "1",
        "true",
        "yes",
        "on",
    )


def in_worker_process_context() -> bool:
    """True when the *process* environment marks a depth-1 worker.

    Command-text assignments such as ``OMG_TEAM_WORKER=0 omg team …`` must never
    authorize or clear this — only real process env is consulted.
    """

    return any(_truthy_process_env(key) for key in _WORKER_ENV_MARKERS)


def _iter_first_party_team_argvs(command: str):
    """Yield argv-after-``team`` for every executable first-party ``omg team`` head.

    Does not interpret command-text env assignments as process identity. Only a
    few words after ``team`` are decoded (op classification is shallow).

    Important (#146 multi-occurrence STOP): a safe/read-only/api head must never
    short-circuit later launch/supervise heads in the same command string.

    Shell metacharacter boundaries are normalized so no-space forms such as
    ``omg team>out launch``, ``omg>out team launch``, ``omg 2>&1 team launch``,
    and ``omg team;echo`` classify correctly.

    Known wrapper options (``env -i`` / ``-S``, ``command -p``, ``nice -n 5``)
    are consumed by :data:`_WRAPPERS` before the head token. Unknown/malformed
    wrapper flags leave a ``-…`` residue head; those fail closed by scanning
    later tokens for ``omg`` + ``team`` (not an unbounded payload scan after a
    non-flag head such as ``echo``).
    """

    search_position = 0
    while match := _DECODED_COMMAND_HEAD.search(command, search_position):
        if _shell_context_is_executable(command, match.start()) is True:
            raw_word = match.group("word")
            base = _executable_basename(raw_word)
            if base == _FIRST_PARTY_TEAM_BIN:
                tail = _next_decoded_words(
                    command, match.end(), limit=10, raise_on_budget=True
                )
                rest = _peel_supported_team_leading_globals(tail)
                if rest and rest[0].lower() == "team":
                    yield [w.lower() for w in rest[1:]]
            elif _should_peel_wrapper_head(raw_word, base):
                words = _semantic_words_from_head_match(
                    command,
                    match,
                    limit=_HEAD_TAIL_TEAM_LIMIT,
                    raise_on_budget=False,
                )
                argv = _team_argv_from_semantic_words(words)
                if argv is not None:
                    yield argv
                remaining = _peel_wrapper_chain(words)
                if (
                    remaining
                    and _token_basename(remaining[0]) == _FIRST_PARTY_TEAM_BIN
                    and len(remaining) == 1
                    and _head_tail_budget_exhausted(command, match)
                ):
                    raise _ShellParseBudgetExceeded
        search_position = match.start() + 1


def _peel_supported_team_leading_globals(words: list[str]) -> list[str]:
    """Drop supported CLI globals that may sit between ``omg`` and ``team``.

    Mirrors ``split_supported_leading_globals`` arity: ``--json`` / ``--safe``
    / ``--yolo`` take no value; ``--project-root`` takes one PATH (or
    ``--project-root=PATH``). Unknown tokens stop the peel so arbitrary
    payloads are not scanned.
    """
    i = 0
    n = len(words)
    while i < n:
        tok = words[i]
        if tok in _TEAM_LEADING_FLAG_OPTS:
            i += 1
            continue
        if tok in _TEAM_LEADING_VALUE_OPTS:
            if i + 1 >= n:
                break
            i += 2
            continue
        if tok.startswith(_TEAM_LEADING_VALUE_EQ_PREFIX):
            i += 1
            continue
        break
    return words[i:]


def _team_argv_is_nested_launch(argv: list[str]) -> bool:
    """Match ``normalize_team_argv`` launch forms for soft-gate DiD.

    Lifecycle verbs + ``shutdown`` alias, numeric ``N[:role]`` shorthand, and
    bare goal strings (any non-reserved non-flag token) rewrite to ``team
    launch`` at the CLI. Identity-bound / read-only reserved ops stay false.
    """
    if not argv:
        # bare ``omg team`` — treat as launch surface (shorthand incomplete)
        return True
    op = argv[0]
    if op in _TEAM_NESTED_LAUNCH_OPS:
        return True
    if _TEAM_SHORTHAND_WORKERS.match(op):
        return True
    # Flags after bare ``team`` are not Form B goals (normalize leaves raw).
    if op.startswith("-") and op not in _TEAM_NON_LAUNCH_OPS:
        return False
    if op in ("hyperplan", "security-research"):
        sub = argv[1] if len(argv) > 1 else ""
        return sub in _TEAM_LEADER_COMPOSITION_OPS
    if op in _TEAM_NON_LAUNCH_OPS:
        return False
    # Form B: ``omg team "fix tests"`` / ``omg team fix tests`` → launch.
    return True


def is_first_party_team_nested_launch(command: str, depth: int = 0) -> bool:
    """Classify obviously nested Team launch/supervise verbs for soft defense-in-depth.

    Authoritative admission remains the OMG Team runtime (``E_TEAM_NESTED_LAUNCH``).
    The hook only recognizes clear launch/lifecycle forms so identity-bound
    ``omg team api …`` still reaches runtime validation. Inspects **every**
    executable first-party Team head in the command (safe first head must not
    mask a later launch), and recurses into ``sh|bash|zsh -c/-lc`` bodies for
    equivalent path/wrapper forms.
    """

    if not command or not isinstance(command, str):
        return False
    try:
        command = _collapse_line_continuations(command)
        for argv in _iter_first_party_team_argvs(command):
            if _team_argv_is_nested_launch(argv):
                return True
        if depth >= 8:
            return False
        search_position = 0
        while match := _SHELL_C_HEAD.search(command, search_position):
            if _shell_context_is_executable(command, match.start()) is True:
                words = _decode_shell_words(
                    _eval_argument_tail(command, match.end())
                )
                body = words[0] if words else ""
                if body and is_first_party_team_nested_launch(body, depth + 1):
                    return True
            search_position = match.start() + 1
        # Wrapper options before ``bash -c`` (``env -i bash -c '…'``) are not
        # visible to :data:`_SHELL_C_HEAD`; peel then inspect the body.
        search_position = 0
        while match := _DECODED_COMMAND_HEAD.search(command, search_position):
            if _shell_context_is_executable(command, match.start()) is True:
                raw_word = match.group("word")
                base = _executable_basename(raw_word)
                if _should_peel_wrapper_head(raw_word, base):
                    words = _semantic_words_from_head_match(
                        command, match, limit=_HEAD_TAIL_TEAM_LIMIT
                    )
                    for body in _shell_c_bodies_from_head_words(words):
                        if body and is_first_party_team_nested_launch(
                            body, depth + 1
                        ):
                            return True
            search_position = match.start() + 1
    except _ShellParseBudgetExceeded:
        # Fail closed on nested-launch classification only when already in worker
        # process context (caller still gates on that).
        return True
    return False


def _bounded_case_pattern_close_positions(command: str) -> frozenset[int]:
    """Bound recursive suffix scans while preserving cached normal parsing."""

    global _case_suffix_scan_depth
    if _case_suffix_scan_depth >= _MAX_CASE_SUFFIX_SCAN_DEPTH:
        raise _ShellParseBudgetExceeded
    _case_suffix_scan_depth += 1
    try:
        return _case_pattern_close_positions(command)
    finally:
        _case_suffix_scan_depth -= 1


@lru_cache(maxsize=128)
def _case_pattern_close_positions(command: str) -> frozenset[int]:
    """Compute real case-pattern terminators once for the whole command."""

    contexts = _shell_context_map(command)
    case_heads: list[re.Match[str]] = []
    search_position = 0
    while match := _CASE_HEAD.search(command, search_position):
        if contexts[match.start()] == _EXECUTABLE_CONTEXT:
            case_heads.append(match)
        search_position = match.start() + 1
    if not case_heads:
        return frozenset()

    case_ends: list[re.Match[str]] = []
    search_position = 0
    while match := _CASE_END.search(command, search_position):
        if contexts[match.start()] == _EXECUTABLE_CONTEXT:
            case_ends.append(match)
        search_position = match.start() + 1

    case_in_ends: dict[int, int] = {}
    for head in case_heads:
        search_position = head.end()
        while match := _CASE_IN.search(command, search_position):
            if contexts[match.start()] == _EXECUTABLE_CONTEXT:
                case_in_ends[head.end()] = match.end()
                break
            search_position = match.start() + 1

    heads_by_end: dict[int, list[re.Match[str]]] = {}
    for head in case_heads:
        heads_by_end.setdefault(head.end(), []).append(head)
    end_counts: dict[int, int] = {}
    for case_end in case_ends:
        end_counts[case_end.end()] = end_counts.get(case_end.end(), 0) + 1

    # Entries are (position after the matching `in`, expects_pattern_close).
    case_stack: list[tuple[int, bool]] = []
    pattern_closes: set[int] = set()
    index = 0
    while index <= len(command):
        for _ in range(end_counts.get(index, 0)):
            if case_stack:
                case_stack.pop()

        for head in heads_by_end.get(index, []):
            # A word `case` while the parent is awaiting its next pattern is
            # pattern data, not a nested case command.
            if case_stack:
                parent_in_end, parent_expects_close = case_stack[-1]
                if index >= parent_in_end and parent_expects_close:
                    continue
            case_stack.append(
                (case_in_ends.get(head.end(), len(command) + 1), True)
            )

        if index == len(command):
            break
        if not case_stack or contexts[index] != _EXECUTABLE_CONTEXT:
            index += 1
            continue

        case_in_end, expects_pattern_close = case_stack[-1]
        if index < case_in_end:
            index += 1
            continue
        if command.startswith(";;&", index):
            case_stack[-1] = (case_in_end, True)
            index += 3
            continue
        if command.startswith((";;", ";&"), index):
            case_stack[-1] = (case_in_end, True)
            index += 2
            continue
        if command[index] == ")" and expects_pattern_close:
            pattern_closes.add(index)
            case_stack[-1] = (case_in_end, False)
        index += 1
    return frozenset(pattern_closes)


def _has_denied_case_command_head(command: str) -> bool:
    """Deny a blocked executable immediately after a case-pattern ``)``."""

    if not _has_executable_match(_CASE_HEAD, command):
        return False
    case_pattern_closes = _case_pattern_close_positions(command)
    search_position = 0
    while match := _CASE_PATTERN_COMMAND_HEAD.search(command, search_position):
        if (
            _shell_context_is_executable(command, match.start()) is True
            and match.start() in case_pattern_closes
            and (
                _decoded_shell_word_is_denied(match.group("word"))
                or _shell_word_has_dynamic_expansion(
                    command,
                    match.start("word"),
                )
            )
        ):
            return True
        search_position = match.start() + 1
    return False


def _decode_eval_body(raw_body: str) -> str:
    return " ".join(_decode_shell_words(raw_body))


def _has_denied_eval_body(command: str, depth: int) -> bool:
    search_position = 0
    while match := _EVAL_HEAD.search(command, search_position):
        if _shell_context_is_executable(command, match.start()) is True:
            body = _decode_eval_body(_eval_argument_tail(command, match.end()))
            if body:
                if _has_dynamic_command_head(body):
                    return True
                if depth >= 8:
                    if re.search(rf"\b{_DENY_BINS}\b", body, re.IGNORECASE):
                        return True
                elif _should_deny_command(body, depth + 1):
                    return True
        search_position = match.start() + 1
    return False


def _has_denied_shell_c_body(command: str, depth: int) -> bool:
    search_position = 0
    while match := _SHELL_C_HEAD.search(command, search_position):
        if _shell_context_is_executable(command, match.start()) is True:
            raw_arguments = _eval_argument_tail(command, match.end())
            words = _decode_shell_words(raw_arguments)
            body = words[0] if words else ""
            if body:
                if _has_dynamic_command_head(body):
                    return True
                if depth >= 8:
                    if re.search(rf"\b{_DENY_BINS}\b", body, re.IGNORECASE):
                        return True
                elif _should_deny_command(body, depth + 1):
                    return True
        search_position = match.start() + 1
    return False


def _has_denied_trap_body(command: str, depth: int) -> bool:
    """Recursively inspect the action argument installed by ``trap``."""

    search_position = 0
    while match := _TRAP_HEAD.search(command, search_position):
        if _shell_context_is_executable(command, match.start()) is True:
            words = _decode_shell_words(
                _eval_argument_tail(command, match.end())
            )
            if words and words[0] == "--":
                words = words[1:]
            if words and not words[0].startswith("-"):
                action = words[0]
                if _has_dynamic_command_head(action):
                    return True
                if depth >= 8:
                    if re.search(
                        rf"\b{_DENY_BINS}\b",
                        action,
                        re.IGNORECASE,
                    ):
                        return True
                elif _should_deny_command(action, depth + 1):
                    return True
        search_position = match.start() + 1
    return False


def _should_deny_command(command: str, eval_depth: int) -> bool:
    if not command or not isinstance(command, str):
        return False
    try:
        command = _collapse_line_continuations(command)
        # Deny when a blocked bin appears in command position, not as an arg.
        if _has_executable_match(_PROMPT_TRANSFORM, command):
            return True
        if _has_executable_match(_DENY_AT_CMD_POS, command):
            return True
        if _has_denied_decoded_command_head(command):
            return True
        if _has_denied_case_command_head(command):
            return True
        # Foreign orchestration only (``omc team``). First-party ``omg team`` is
        # intentionally NOT an external-CLI deny — runtime owns Team admission.
        if _has_foreign_omc_team(command):
            return True
        # sh/bash/zsh -c/-lc command strings are recursively inspected.
        if _has_denied_shell_c_body(command, eval_depth):
            return True
        if _has_denied_trap_body(command, eval_depth):
            return True
        if _has_executable_match(_EVAL, command):
            return True
        if _has_denied_eval_body(command, eval_depth):
            return True
    except _ShellParseBudgetExceeded:
        return True
    return False


def should_deny_command(command: str) -> bool:
    return _should_deny_command(command, 0)


